update public.learning_paths
set
  title = 'World Religions',
  goal = 'World Religions',
  summary = 'World Religions introduces students to major religious traditions, Indigenous and diasporic religious worlds, new religious movements, nonreligion, and cross-tradition themes through academic methods. Students study texts, rituals, ethics, material culture, social power, migration, media, and contemporary public life while learning that traditions are internally diverse, historically changing, and never reducible to a list of beliefs.',
  data = $wreljson${"slug": "world-religions", "title": "World Religions", "description": "World Religions introduces students to major religious traditions, Indigenous and diasporic religious worlds, new religious movements, nonreligion, and cross-tradition themes through academic methods. Students study texts, rituals, ethics, material culture, social power, migration, media, and contemporary public life while learning that traditions are internally diverse, historically changing, and never reducible to a list of beliefs.", "topics": [{"id": "777ad784-ece5-431f-b75a-0c027a2261b6", "type": "topic", "title": "World Religions as a Category: Map, Method, and Critique", "description": "This section builds the conceptual and factual depth needed for the module while keeping comparison responsible, evidence-based, and attentive to lived practice.", "children": [{"id": "c343b009-5dc9-4cb5-b34c-d9c2dd8ce872", "type": "subtopic", "title": "Why use the category?", "children": [{"id": "30dc290c-9079-4a29-93d1-745ee7991956", "type": "concept", "title": "Survey logic"}, {"id": "6467bc6b-0300-4847-bb35-744e8f55a1e5", "type": "concept", "title": "Pedagogical usefulness"}, {"id": "6c99a796-fbaf-4ec3-b405-73edd94980a0", "type": "concept", "title": "Limits of neat traditions"}], "description": "Students learn that the category can help organize a broad field, but it is not a neutral description of reality."}, {"id": "7159d1cd-3cf7-4bf1-8325-205fa9b346c3", "type": "subtopic", "title": "Critiques of the world religions paradigm", "children": [{"id": "e6f0048e-522f-4a28-ad8a-5c9f9ac23e1d", "type": "concept", "title": "Eurocentrism"}, {"id": "f9bb31c7-e74f-47d5-9849-a43ccbab671c", "type": "concept", "title": "Protestant model of religion"}, {"id": "115458a2-9e82-470c-abaa-7df86120a1fc", "type": "concept", "title": "Power and classification"}], "description": "Students see how the category can privilege large, textual, institutionally visible traditions and marginalize local or Indigenous practices."}, {"id": "2c740f69-9b79-4cbd-9902-e5a7aec97861", "type": "subtopic", "title": "Responsible comparison", "children": [{"id": "baf753f4-9cdf-4a0f-87e2-422f7e42c3a1", "type": "concept", "title": "Specific cases"}, {"id": "a3df1ad2-7445-4870-ae2e-c910482479d3", "type": "concept", "title": "Internal diversity"}, {"id": "68e99785-1842-4a7e-bb1d-37d5ed55e2bc", "type": "concept", "title": "Comparison with caveats"}], "description": "The course begins with humility about scale, translation, evidence, and the danger of flattening traditions."}]}, {"id": "63930ee3-0ea8-4990-b82d-3e100d6cafa0", "type": "topic", "title": "Tools for Comparing Religions: Myth, Ritual, Text, Ethics, Experience, and Community", "description": "This section builds the conceptual and factual depth needed for the module while keeping comparison responsible, evidence-based, and attentive to lived practice.", "children": [{"id": "afea2221-1fe3-45cb-920c-253d427fd08a", "type": "subtopic", "title": "Myth and narrative", "children": [{"id": "11442a9c-52be-4385-913d-82518aad7fd5", "type": "concept", "title": "Cosmogony"}, {"id": "5498d9ab-0854-4e2e-b341-6812e83430cf", "type": "concept", "title": "Hero and ancestor stories"}, {"id": "a01b26a0-20a0-49ce-bc58-534eec6bf958", "type": "concept", "title": "Ritual retelling"}], "description": "Students learn to read sacred stories as meaning-making narratives, not simply as false claims or literal history."}, {"id": "53db2315-62ec-4d0e-b788-c4473a76df9d", "type": "subtopic", "title": "Ritual and practice", "children": [{"id": "5237e034-8608-468d-9c49-933033efd573", "type": "concept", "title": "Rites of passage"}, {"id": "297123dd-47c1-44cc-8bc3-66923c7e7e2a", "type": "concept", "title": "Purity and sacrifice"}, {"id": "c542af1c-2c1e-4df6-98bd-f20d82233157", "type": "concept", "title": "Pilgrimage and festival"}], "description": "The point is to notice what people do with bodies, objects, calendars, food, sound, pilgrimage, and repeated action."}, {"id"